"""Assets visuais da área Analisar, recortados da cartela enviada pelo Gabriel (fundo removido, proporção preservada).
Prefixos: cl_ = classes de ativo, m_ = Caramelo (poses), i_ = indicadores, c_ = conquistas/emblemas. Cada item: (WebP em base64, largura, altura).
Módulo só de dados: os PNGs originais completos ficam na pasta assets_analisar/ (organizados por finalidade)."""
from __future__ import annotations

IMAGENS = {
    "cl_acoes": ("", 150, 92),
    "cl_fiis": ("", 147, 92),
    "cl_renda_fixa": ("", 148, 92),
    "cl_cripto": ("", 138, 92),
    "cl_etfs": ("", 139, 92),
    "cl_commodities": ("", 148, 92),
    "cl_bdrs": ("", 136, 92),
    "cl_outros": ("", 132, 92),
    "m_lupa": ("", 225, 230),
    "m_duvida": ("", 209, 230),
    "m_vitoria": ("", 230, 227),
    "m_notebook": ("", 230, 225),
    "m_trofeu": ("", 230, 224),
    "m_formado": ("", 211, 230),
    "i_crescimento": ("", 120, 119),
    "i_candles": ("", 120, 119),
    "i_pizza": ("", 118, 120),
    "i_relatorio": ("", 101, 120),
    "i_lupa_grafico": ("", 120, 117),
    "i_escudo_grafico": ("", 111, 120),
    "i_alvo": ("", 117, 120),
    "i_ideia": ("", 95, 120),
    "c_estrela": ("", 130, 127),
    "c_medalha": ("", 95, 130),
    "c_escudo_coroa": ("", 120, 130),
    "c_hex_grafico": ("", 118, 130),
    "c_hex_alvo": ("", 120, 130),
    "c_hex_formatura": ("", 121, 130),
    "c_hex_diamante": ("", 117, 130),
    "c_bau": ("", 130, 88),
}


def uri(nome: str) -> str:
    d = IMAGENS.get(nome)
    return f"data:image/webp;base64,{d[0]}" if d else ""


def existe(nome: str) -> bool:
    return nome in IMAGENS


def img(nome: str, classe: str = "", alt: str = "") -> str:
    """Tag <img> pronta (vazia se o asset não existir). Largura/altura reais evitam a imagem 'pular' ao carregar."""
    d = IMAGENS.get(nome)
    if not d:
        return ""
    cl = f" class='{classe}'" if classe else ""
    return f"<img{cl} src='{uri(nome)}' width='{d[1]}' height='{d[2]}' alt='{alt}' loading='lazy' decoding='async'>"
